# This file is not generated by Stainless and is preserved across codegen runs.
# It holds unit tests for the hand-written inference secrets delete_and_poll.
#
# The DELETE answers 204 before the secret is gone, so delete_and_poll waits for
# the GET to return 404, keeps polling through other API errors, and reports the
# last of them only when the polling timeout runs out.
from __future__ import annotations

from typing import Any, List

import httpx
import respx
import pytest

from gcore import Gcore, AsyncGcore

base_url = "http://127.0.0.1:4010"
NAME = "my-aws-iam-secret"
PATH = f"{base_url}/cloud/v3/inference/1/secrets/{NAME}"

_SECRET = {"name": NAME, "type": "aws-iam", "data": {"aws_access_key_id": "AKIA", "aws_secret_access_key": "secret"}}


def _responses(statuses: List[int]) -> List[httpx.Response]:
    return [httpx.Response(s, json=_SECRET if s == 200 else {"message": "error"}) for s in statuses]


def _sync_client(sleeps: List[float]) -> Gcore:
    client = Gcore(base_url=base_url, api_key="test", cloud_project_id=1, max_retries=0)
    client.cloud.inference.secrets._sleep = sleeps.append  # type: ignore[method-assign]
    return client


def _async_client(sleeps: List[float]) -> AsyncGcore:
    client = AsyncGcore(base_url=base_url, api_key="test", cloud_project_id=1, max_retries=0)

    async def _record(seconds: float) -> None:
        sleeps.append(seconds)

    client.cloud.inference.secrets._sleep = _record  # type: ignore[method-assign]
    return client


@respx.mock
def test_waits_until_the_secret_is_gone() -> None:
    sleeps: List[float] = []
    respx.delete(PATH).mock(return_value=httpx.Response(204))
    get = respx.get(PATH).mock(side_effect=_responses([200, 200, 404]))

    _sync_client(sleeps).cloud.inference.secrets.delete_and_poll(NAME, polling_interval_seconds=2)

    assert get.call_count == 3
    assert sleeps == [2, 2]


@respx.mock
def test_keeps_polling_through_a_transient_error() -> None:
    sleeps: List[float] = []
    respx.delete(PATH).mock(return_value=httpx.Response(204))
    get = respx.get(PATH).mock(side_effect=_responses([500, 200, 404]))

    _sync_client(sleeps).cloud.inference.secrets.delete_and_poll(NAME)

    assert get.call_count == 3


@respx.mock
def test_timeout_reports_the_secret_and_the_last_error(monkeypatch: Any) -> None:
    sleeps: List[float] = []
    respx.delete(PATH).mock(return_value=httpx.Response(204))
    respx.get(PATH).mock(return_value=httpx.Response(502, json={"message": "bad gateway"}))
    # Each sleep advances the clock, so the timeout runs out without waiting.
    now = [1000.0]
    monkeypatch.setattr("gcore.resources.cloud.inference.secrets_custom.time.time", lambda: now[0])
    client = _sync_client(sleeps)
    client.cloud.inference.secrets._sleep = lambda s: now.__setitem__(0, now[0] + s)  # type: ignore[method-assign]

    with pytest.raises(TimeoutError, match=rf"{NAME} is still reported after delete.*502"):
        client.cloud.inference.secrets.delete_and_poll(NAME, polling_interval_seconds=1, polling_timeout_seconds=3)


# The interval does not divide the timeout, so the last wait is cut short and
# the final check lands on the deadline instead of giving up a sleep early.
@respx.mock
def test_last_check_lands_on_the_deadline(monkeypatch: Any) -> None:
    respx.delete(PATH).mock(return_value=httpx.Response(204))
    get = respx.get(PATH).mock(side_effect=_responses([200, 200, 404]))
    now = [1000.0]
    monkeypatch.setattr("gcore.resources.cloud.inference.secrets_custom.time.time", lambda: now[0])
    sleeps: List[float] = []
    client = _sync_client(sleeps)

    def _advance(seconds: float) -> None:
        sleeps.append(seconds)
        now[0] += seconds

    client.cloud.inference.secrets._sleep = _advance  # type: ignore[method-assign]

    client.cloud.inference.secrets.delete_and_poll(NAME, polling_interval_seconds=5, polling_timeout_seconds=9)

    assert get.call_count == 3
    assert sleeps == [5, 4]


@respx.mock
def test_delete_error_is_raised_without_polling() -> None:
    respx.delete(PATH).mock(return_value=httpx.Response(409, json={"message": "conflict"}))
    get = respx.get(PATH).mock(side_effect=_responses([200]))

    with pytest.raises(Exception, match="409"):
        _sync_client([]).cloud.inference.secrets.delete_and_poll(NAME)

    assert get.call_count == 0


@respx.mock
async def test_async_waits_until_the_secret_is_gone() -> None:
    sleeps: List[float] = []
    respx.delete(PATH).mock(return_value=httpx.Response(204))
    get = respx.get(PATH).mock(side_effect=_responses([200, 404]))

    await _async_client(sleeps).cloud.inference.secrets.delete_and_poll(NAME, polling_interval_seconds=2)

    assert get.call_count == 2
    assert sleeps == [2]
